# 22 autonomous / special regions — research 2026-11-14 (sources in each entry)
U = "2026-11-14"

def R(parent, typ, asof, st, summary, leader, agenda, projects, biz, needs, watch, risk, sources, en):
    return {"parent": parent, "type": typ, "updated": U, "asof": asof, "status": st, "summary": summary, "leader": leader,
            "agenda": agenda, "gov": {}, "projects": projects, "biz": biz, "needs": needs, "tenders": [], "oda": [], "krwins": [], "krsupport": [],
            "watch": watch, "risk": {**risk[0], "checked": U}, "risk_en": risk[1], "sources": [{"title": t, "url": u} for t, u in sources], "en": en}

def S(capital, est, law, gov, powers, reserved, nxt):
    return {"capital": capital, "established": est, "law": law, "government": gov, "powers": powers, "reserved": reserved, "next": nxt}

def B(title, fit, why, target, basis=""):
    return {"title": title, "fit": fit, "why": why, "target": target, "basis": basis}

def P(title, ministry, status, detail="", budget="", url=""):
    x = {"title": title, "ministry": ministry, "status": status, "detail": detail}
    if budget: x["budget"] = budget
    if url: x["url"] = url
    return x

def E(summary, leader, status, agenda, biz, needs, watch):
    return {"summary": summary, "leader": leader, "status": status, "agenda": agenda, "biz": biz, "needs": needs, "watch": watch}

